import torch


def _resolve_dtype(d):
    if isinstance(d, torch.dtype):
        return d
    return getattr(torch, str(d).replace("torch.", ""))


def gen_inputs(ctx, device):
    shape = ctx["x__shape"]
    dtype = _resolve_dtype(ctx["x__dtype"])
    # K0 is only defined for x > 0, so generate positive inputs only.
    x = torch.rand(shape, dtype=dtype, device=device) + 0.1
    return {"x": x}


def run(x):
    return torch.special.modified_bessel_k0(x)
